const readRepoFile = (rel: string): string => readFileSync(repoPath(rel), 'utf8');
const loadYaml = <T = unknown>(rel: string): T => parseYaml(readRepoFile(rel)) as T;
const isExecutable = (rel: string): boolean => (statSync(repoPath(rel)).mode & 0o100) !== 0;

